{
  "title": "The Mirror's Gate Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a ruined map of the city.",
      "visual_description": "Mara stands by a cracked stone table under a broken archway, unrolling a faded parchment map while wind stirs debris around her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver arrives through a shattered window.",
      "visual_description": "A clear diving helmet emerges from a stained-glass window, reflecting fractured light as the Glass Diver steps into the room, coat shimmering.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers to life on a dusty shelf.",
      "visual_description": "An oil lamp with a single glowing eye in its flame casts long shadows, its voice crackling as it warns of a cursed tower ahead.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the Glass Diver meet the Tin Fox at the city's edge.",
      "visual_description": "A small metal fox with a key-wind tail and blue glass eyes clicks across cobblestones, stopping to tilt its head at the pair.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "They pass through the castle gates, now rusted and ajar.",
      "visual_description": "Massive iron gates, covered in orange rust and creeping ivy, hang half-open against a pale sky as the group steps through.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp warns of a magic door ahead.",
      "visual_description": "The lamp's flame flares as it speaks, illuminating a door made of rippling silver that reflects the sky like a mirror.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver swims through the silver door's surface.",
      "visual_description": "The Glass Diver presses a hand to the magic door, then steps through as if diving into water, ripples spreading across the silver.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara and the Tin Fox find a sleeping bureaucrat in a collapsed hall.",
      "visual_description": "A figure snores softly, using a ledger book as a pillow, stamped papers stuck to sleeves, oblivious to the debris around him.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The Oracle Lamp reveals the rumors of dragons are false echoes.",
      "visual_description": "The lamp's eye pulses as it shows a vision of old royal banners flapping, the dragon rumor merely a trick of wind and shadow.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The group navigates a cursed tower's spiraling stairs.",
      "visual_description": "Twisting stone steps circle upward, faint blue runes glowing on the walls, the air thick with dust and ancient magic.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "They find the captive behind a wall of shifting mirrors.",
      "visual_description": "A maze of mirrored panels surrounds a central figure, each surface showing a different reflection of the room.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver shatters the mirror wall with a diving kick.",
      "visual_description": "The Glass Diver leaps, helmet gleaming, and kicks the central mirror, which cracks and falls like rain of glass shards.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Sleeping Tax Collector wakes and stamps an exit permit.",
      "visual_description": "Bleary-eyed, the collector pulls a stamp from a sleeve and presses it onto a scrap of paper, then yawns and returns to sleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Old royal banners line the escape route, tattered and faded.",
      "visual_description": "Long strips of cloth, once bright, now gray, hang from stone pillars, stirring in a cold breeze as the group hurries beneath them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Frightened townspeople watch from boarded windows.",
      "visual_description": "Eyes peer through cracks in wooden shutters, hands clutching cloth, faces pale, as the rescue party moves down the street.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols clank in the distance, horns sounding.",
      "visual_description": "Glints of metal and low horn notes echo from a side street, but the patrols are still far, moving in formation.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the final bridge, stone crumbling beneath.",
      "visual_description": "A long stone bridge arches over a chasm, cracks spreading underfoot, the group sprinting as pieces fall into the void.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes as the bridge collapses behind them.",
      "visual_description": "The bridge gives way in a cloud of dust and stone, the far edge safe, the ruined city receding as sunlight breaks through clouds.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

